167	function getContentFromModel(ecModel: GlobalModel) {
168	
169	    const result = groupSeries(ecModel);
170	
171	    return {
172	        value: zrUtil.filter([
173	                assembleSeriesWithCategoryAxis(result.seriesGroupByCategoryAxis),
174	                assembleOtherSeries(result.other)
175	            ], function (str) {
176	                return !!str.replace(/[\n\t\s]/g, '');
177	            }).join('\n\n' + BLOCK_SPLITER + '\n\n'),
178	
179	        meta: result.meta
180	    };
181	}
