480	/**
481	 * @inner
482	 */
483	function tryMergeDataOption(newData: DataList, originalData: DataList) {
484	    return zrUtil.map(newData, function (newVal, idx) {
485	        const original = originalData && originalData[idx];
486	        if (zrUtil.isObject(original) && !zrUtil.isArray(original)) {
487	            const newValIsObject = zrUtil.isObject(newVal) && !zrUtil.isArray(newVal);
488	            if (!newValIsObject) {
489	                newVal = {
490	                    value: newVal
491	                } as DataItem;
492	            }
493	            // original data has name but new data has no name
494	            const shouldDeleteName = original.name != null && (newVal as DataItem).name == null;
495	            // Original data has option
496	            newVal = zrUtil.defaults((newVal as DataItem), original);
497	            shouldDeleteName && (delete (newVal as DataItem).name);
498	            return newVal;
499	        }
500	        else {
501	            return newVal;
502	        }
503	    });
504	}
